"""Render audited V4.9 JSON to offline HTML and CSV without network calls."""
import csv,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
d=json.loads((ROOT/'beanlens-bom-v4.9.json').read_text());rows=d['items']
cols=[('id','编号'),('category','分组'),('name','物料'),('model','型号/材料'),('spec','规格尺寸'),('qty','数量'),('unit','单位'),('selection','方案'),('readiness','下单状态'),('price_cny','人民币单价'),('price_basis','报价依据'),('check','核对事项'),('sources','资料来源')]
with (ROOT/'beanlens-bom-v4.9.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f);w.writerow([v for k,v in cols]);w.writerows([[(' | '.join(r[k]) if isinstance(r[k],list) else r[k]) for k,v in cols] for r in rows])
e=lambda s:html.escape(str(s))
body=''
for r in rows:
 links=' · '.join(f'<a href="{e(u)}">资料{i+1}</a>' for i,u in enumerate(r['sources']))
 body+=f'''<tr data-id="{e(r['id'])}" data-selection="{e(r['selection'])}"><td><b>{e(r['id'])}</b><br>{e(r['category'])}</td><td><b>{e(r['name'])}</b><br>{e(r['model'])}<p>{e(r['spec'])}</p>{links}</td><td>{r['qty']} {e(r['unit'])}<br>{e(r['selection'])}</td><td>{e(r['readiness'])}<p>{e(r['check'])}</p></td><td>{('¥'+format(r['price_cny'],'.2f')) if r['price_cny'] is not None else '待询价'}<p>{e(r['price_basis'])}</p></td></tr>'''
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>BeanLens V4.9 采购表</title><style>*{box-sizing:border-box}body{margin:0;background:#f2f3ec;color:#263b32;font:16px/1.6 system-ui,-apple-system,"PingFang SC",sans-serif}main{max-width:1550px;padding:28px;margin:auto}h1{font-size:34px}a{color:#177b58}nav,.filters{display:flex;gap:16px;flex-wrap:wrap}section{background:#fffef9;border:1px solid #d8dfd3;padding:20px;margin:20px 0;border-radius:10px}.filters{align-items:center;margin-bottom:15px}input,select,button{font:inherit;padding:9px;border:1px solid #c4cec0;border-radius:6px;background:white;color:inherit}input{min-width:260px;flex:1}.table{overflow:auto;max-height:78vh}table{border-collapse:collapse;width:100%;min-width:1050px}td,th{padding:13px;text-align:left;vertical-align:top;border-bottom:1px solid #d8dfd3}th{position:sticky;top:0;background:#e9f1e5}td:first-child{width:110px}td:nth-child(2){width:38%}td:nth-child(3){width:110px}td:nth-child(4){width:30%}p{margin:8px 0}td p,td a{font-size:14px;color:#5a6e5b}td:last-child{width:160px}.note{background:#fff0d8}button{cursor:pointer}[hidden]{display:none!important}input:focus-visible,select:focus-visible,button:focus-visible{outline:3px solid #177b58}@media print{.filters,nav{display:none}.table{max-height:none;overflow:visible}th{position:static}table{min-width:0;font-size:10px}td,th{padding:4px}main{padding:0}}</style><main><small>BEANLENS · 2026-10-16 · PROPOSAL</small><h1>V4.9 采购：常见电源件 + 连续 PP 料斗</h1><nav><a href="../revision-v4.9/beanlens-power-and-feed-v4.9.html">四页接线 / 豆路图</a><a href="../revision-v4.9/README.md">推荐理由、淘宝关键词和估价</a><a href="beanlens-bom-v4.9.csv">完整CSV</a><a href="beanlens-bom-v4.9.json">JSON</a><a href="../assembly-v4.8/beanlens-assembly-v4.8.html">保留机架 / 双屏图</a></nav><section class="note"><b>与 V4.8 的变化</b><p>A07 改航嘉24V/5A；A08/A17改两块XL4016E1整板（5V/6V）；P05改TB1506两条，P16只给TB-A配两段3位桥。电源另用P11外置低压盒，不塞原21mm后腔。原明纬/Pololu/WAGO/NKK另列备选，已有则复用。</p><p>F04改连续4片PP2料斗；F05仅PP3顶法兰/绝缘后框；F18新增PP6五孔上座；G12改POM10五孔下座140×18。F14双法兰取消，数量0。旧八片模板和五窗叠片尺寸不可混用。机架和9片木板沿用V4.8。</p></section><section><b>价格与下单状态</b><p>电源包规划约¥200–370，属于估价，不是淘宝购物车报价；表中未知单价继续留空。已知用户报价小计仍¥386.90（含其他物料），不能把电源估价当作全机总价。已有和备选不得重复计入。CNC厚料首台加工费未定。</p><p>共 __COUNT__ 项，含已有、备选、取消历史行。未完成实物带载、带豆、热与称重验收。G10/G20/光束避让仍需试配。</p></section><section><div class="filters"><input id="search" type="search" aria-label="搜索物料" placeholder="搜索型号、编号、规格"><select id="sel" aria-label="方案筛选"><option value="">全部方案</option><option>主方案</option><option>备选</option><option>已有</option><option>套件包含</option><option>历史不采购</option></select><button id="reset">清除</button><output id="count"></output></div><div class="table"><table><thead><tr><th>编号</th><th>型号 / 尺寸 / 来源</th><th>数量 / 方案</th><th>下单核对</th><th>单价</th></tr></thead><tbody>__BODY__</tbody></table></div></section></main><script>const q=document.getElementById('search'),sel=document.getElementById('sel'),rows=[...document.querySelectorAll('tbody tr')];function filter(){let n=0;rows.forEach(r=>{r.hidden=!(r.textContent.toLowerCase().includes(q.value.toLowerCase())&&(!sel.value||r.dataset.selection===sel.value));if(!r.hidden)n++});document.getElementById('count').textContent=`${n} / ${rows.length} 项`}q.oninput=sel.onchange=filter;document.getElementById('reset').onclick=()=>{q.value=sel.value='';filter()};filter()</script></html>'''
(ROOT/'beanlens-procurement-v4.9.html').write_text(page.replace('__COUNT__',str(len(rows))).replace('__BODY__',body))
print(f'V4.9: {len(rows)} rows')
